const assert = require('node:assert');
const { proc, f2 } = require('./util');

assert.deepStrictEqual(
  proc([{ a: 1, n: 'x' }, null, { a: 0, n: 'y' }, undefined, { a: '1', n: 'z' }]),
  ['X', 'y', 'Z'],
);
assert.deepStrictEqual(proc([]), []);

assert.deepStrictEqual(f2(' a, b ,, c ,'), ['a', 'b', 'c']);
assert.deepStrictEqual(f2(''), []);

console.log('ok');

